WITH exploded AS (SELECT id, service, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, attr_value), unpacked AS (SELECT id, service, attr_value, CAST((status_code & 2) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded), enriched AS (SELECT *, DENSE_RANK() OVER (PARTITION BY service ORDER BY status_code_high NULLS LAST) AS status_code_high_dense_rank, RANK() OVER (PARTITION BY service ORDER BY status_code_high) AS status_code_high_rank FROM unpacked), scored AS (SELECT *, DENSE_RANK() OVER w_part AS status_code_high_dense_rank_2, SUM(status_code_high) OVER w_recent AS service_sum_status_code_high, PERCENT_RANK() OVER w_part AS status_code_high_percent_rank, SUM(status_code_high) OVER w_recent AS service_sum_status_code_high_2, PERCENT_RANK() OVER w_ordered AS status_code_high_percent_rank_2 FROM enriched WINDOW w_part AS (PARTITION BY service ORDER BY status_code_high DESC NULLS LAST), w_recent AS (PARTITION BY service), w_ordered AS (PARTITION BY service ORDER BY status_code_high)), totals AS (SELECT CASE WHEN status_code_high_percent_rank_2 >= 0.74 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_percent_rank_2_tier, COUNT(*) FILTER (WHERE service = 'billing') AS billing_rows, SIZE(COLLECT_SET(service)) AS num_services, APPROX_PERCENTILE(has_fault, ARRAY(0.25, 0.5, 0.75)) AS has_fault_quartiles, APPROX_PERCENTILE(status_code_high_dense_rank, 0.9) AS status_code_high_dense_rank_p90, COUNT(DISTINCT service) AS distinct_services, SUM(status_code_high) FILTER (WHERE service = 'search') AS search_total_status_code_high FROM scored GROUP BY CASE WHEN status_code_high_percent_rank_2 >= 0.74 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) FILTER (WHERE service = 'billing') >= 1) SELECT status_code_high_percent_rank_2_tier, num_services, status_code_high_dense_rank_p90, search_total_status_code_high FROM totals ORDER BY search_total_status_code_high DESC, status_code_high_dense_rank_p90 DESC;
